-- PHB v3.5 spell definitions, batch 01.
-- Source: individual spell descriptions, pp. 196-303. Safe to re-run.
INSERT OR IGNORE INTO dnd35_spells
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,school_id,subschool,casting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,saving_throw_text,save,spell_resistance,spell_resistance_text) VALUES
  ('phb-spell-acid-fog','phb-3.5','196','acid-fog','Acid Fog','Acid fog creates a billowing mass of misty vapors similar to that produced by a solid fog spell (page 281).','Acid fog creates a billowing mass of misty vapors similar to that produced by a solid fog spell (page 281). In addition to slowing creatures down and obscuring sight, this spell’s vapors are highly acidic.',0,NULL,1,'phb-spell-school-conjuration','Creation','1 standard action','standard','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Fog spreads in 20-ft. radius, 20 ft. high','1 round/level','None',NULL,'no','No'),
  ('phb-spell-acid-splash','phb-3.5','196','acid-splash','Acid Splash','You fire a small orb of acid at the target. You must succeed on a ranged touch attack to hit your target.','You fire a small orb of acid at the target. You must succeed on a ranged touch attack to hit your target. The orb deals 1d3 points of acid damage.',0,NULL,1,'phb-spell-school-conjuration','Creation','1 standard action','standard','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One missile of acid','Instantaneous','None',NULL,'no','No'),
  ('phb-spell-aid','phb-3.5','196','aid','Aid','Aid grants the target a +1 morale bonus on attack rolls and saves against fear effects, plus temporary hit points equal to 1d8 + caster…','Aid grants the target a +1 morale bonus on attack rolls and saves against fear effects, plus temporary hit points equal to 1d8 + caster level (to a maximum of 1d8+10 temporary hit points at caster level 10th).',0,NULL,1,'phb-spell-school-enchantment','Compulsion','1 standard action','standard','Touch','Living creature touched',NULL,NULL,'1 min./level','None',NULL,'yes','Yes (harmless)'),
  ('phb-spell-air-walk','phb-3.5','196','air-walk','Air Walk','The subject can tread on air as if walking on solid ground. Moving upward is similar to walking up a hill.','The subject can tread on air as if walking on solid ground. Moving upward is similar to walking up a hill. The maximum upward or downward angle possible is 45 degrees, at a rate equal to one-half the air walker’s normal speed.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action','standard','Touch','Creature (Gargantuan or smaller) touched','10-ft.-radius emanation, centered on you',NULL,'10 min./level','None',NULL,'yes','Yes (harmless)'),
  ('phb-spell-alarm','phb-3.5','197','alarm','Alarm','Alarm sounds a mental or audible alarm each time a creature of Tiny or larger size enters the warded area or touches it.','Alarm sounds a mental or audible alarm each time a creature of Tiny or larger size enters the warded area or touches it. A creature that speaks the password (determined by you at the time of casting) does not set off the alarm.',0,NULL,1,'phb-spell-school-abjuration',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)',NULL,'20-ft.-radius emanation centered on a point in space',NULL,'2 hours/level (D)','None',NULL,'no','No'),
  ('phb-spell-align-weapon','phb-3.5','197','align-weapon','Align Weapon','Align weapon makes a weapon good, evil, lawful, or chaotic, as you choose.','Align weapon makes a weapon good, evil, lawful, or chaotic, as you choose. A weapon that is aligned can bypass the damage reduction of certain creatures, usually outsiders of the opposite alignment.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action','standard','Touch','Weapon touched or fifty projec- tiles (all of which must be in contact with each other at the time of casting)',NULL,NULL,'1 min./level','Will negates (harmless, object)','will','yes','Yes (harmless, object)'),
  ('phb-spell-alter-self','phb-3.5','197','alter-self','Alter Self','You assume the form of a creature of the same type as your normal form (such as humanoid or magical beast).','You assume the form of a creature of the same type as your normal form (such as humanoid or magical beast). The new form must be within one size category of your normal size.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'10 min./level (D)',NULL,NULL,'no','No'),
  ('phb-spell-analyze-dweomer','phb-3.5','197','analyze-dweomer','Analyze Dweomer','You discern all spells and magical properties present in a number of creatures or objects.','You discern all spells and magical properties present in a number of creatures or objects. Each round, you may examine a single creature or object that you can see as a free action.',0,NULL,1,'phb-spell-school-divination',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One object or creature per caster level',NULL,NULL,'1 round/level (D)','None or Will negates; see text','will','no','No'),
  ('phb-spell-animal-growth','phb-3.5','198','animal-growth','Animal Growth','A number of animals grow to twice their normal size and eight times their normal weight.','A number of animals grow to twice their normal size and eight times their normal weight. This alteration changes each animal’s size category to the next largest (from Large to Huge, for example), grants it a +8 size bonus to Strength and a +4 size bonus to…',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action','standard','Medium (100 ft. + 10 ft./level)','Up to one animal (Gargantuan or smaller) per two levels, no two of which can be more than 30 ft. apart',NULL,NULL,'1 min./level','Fortitude negates','fort','yes','Yes'),
  ('phb-spell-animal-messenger','phb-3.5','198','animal-messenger','Animal Messenger','You compel a Tiny animal to go to a spot you designate. The most common use for this spell is to get an animal to carry a message to your…','You compel a Tiny animal to go to a spot you designate. The most common use for this spell is to get an animal to carry a message to your allies.',0,NULL,1,'phb-spell-school-enchantment','Compulsion','1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One Tiny animal',NULL,NULL,'One day/level','None; see text',NULL,'yes','Yes'),
  ('phb-spell-animal-shapes','phb-3.5','198','animal-shapes','Animal Shapes','You transform up to one willing creature per caster level into an animal of your choice; the spell has no effect on unwilling creatures.','You transform up to one willing creature per caster level into an animal of your choice; the spell has no effect on unwilling creatures. See Errata.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','Up to one willing creature per level, all within 30 ft. of each other',NULL,NULL,'1 hour/level (D)','None; see text',NULL,'yes','Yes (harmless)'),
  ('phb-spell-animal-trance','phb-3.5','198','animal-trance','Animal Trance','Your swaying motions and music (or singing, or chanting) compel animals and magical beasts to do nothing but watch you.','Your swaying motions and music (or singing, or chanting) compel animals and magical beasts to do nothing but watch you. Only a creature with an Intelligence score of 1 or 2 can be fascinated by this spell.',0,NULL,1,'phb-spell-school-enchantment','Compulsion','1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','Animals or magical beasts with Intelligence 1 or 2',NULL,NULL,'Concentration','Will negates; see text','will','yes','Yes'),
  ('phb-spell-animate-dead','phb-3.5','198','animate-dead','Animate Dead','This spell turns the bones or bodies of dead creatures into undead skeletons or zombies that follow your spoken commands.','This spell turns the bones or bodies of dead creatures into undead skeletons or zombies that follow your spoken commands. The undead can follow you, or they can remain in an area and attack any creature (or just a specific kind of creature) entering the place.',0,NULL,1,'phb-spell-school-necromancy',NULL,'1 standard action','standard','Touch','One or more corpses touched',NULL,NULL,'Instantaneous','None',NULL,'no','No'),
  ('phb-spell-animate-objects','phb-3.5','199','animate-objects','Animate Objects','You imbue inanimate objects with mobility and a semblance of life.','You imbue inanimate objects with mobility and a semblance of life. Each such animated object then immediately attacks whomever or whatever you initially designate.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action','standard','Medium (100 ft. + 10 ft./level)','One Small object per caster level; see text',NULL,NULL,'1 round/level','None',NULL,'no','No'),
  ('phb-spell-animate-plants','phb-3.5','199','animate-plants','Animate Plants','You imbue inanimate plants with mobility and a semblance of life.','You imbue inanimate plants with mobility and a semblance of life. Each animated plant then immediately attacks whomever or whatever you initially designate as though it were an animated object of the appropriate size category.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One Large plant per three caster levels or all plants within range; see text',NULL,NULL,'1 round/level or 1 hour/level; see text','None',NULL,'no','No');
